43:{
44:     size_t size_left = size;
45:     size_t arglen;
46:     char * argv[67];
47:     char exename[] = "flac";
48:     char filename[] = "/tmp/fuzzXXXXXX";
49:     int numarg = 0, maxarg, pad;
50:     int file_to_fuzz;
51:
52:     flac__utils_verbosity_ = 0;
53:     share__opterr = 0;
54:     share__optind = 0;
55:
56:
57:     if(size < 2)
58:             return 0;
59:
60:     maxarg = data[0] & 63;
61:     pad = data[0] & 64;
62:     size_left--;
63:
64:     argv[0] = exename;
65:     numarg++;
66:
67:     /* Check whether input is zero delimited */
68:     while((arglen = strnlen((char *)data+(size-size_left),size_left)) < size_left && numarg < maxarg) {
69:             argv[numarg++] = (char *)data+(size-size_left);
70:             size_left -= arglen + 1;
71:     }
72:
73:     file_to_fuzz = mkstemp(filename);
74:
75:     if (file_to_fuzz < 0)
76:             abort();
77:     write(file_to_fuzz,data+(size-size_left),size_left);
78:     if(pad)
79:             write(file_to_fuzz,"\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00",12);
80:     close(file_to_fuzz);
81:
82:     argv[numarg++] = filename;
83:
84:     main_to_fuzz(numarg,argv);
85:
86:     unlink(filename);
87:
88:     return 0;
